We are now moving to **Step 20: Implement the SharedWorker Data Pipeline**.

### Architectural Context
*   **Thesis**: The UI must process 1,000+ updates per second without freezing. A **SharedWorker** is the only viable architecture to offload all network I/O and data processing from the main UI thread, acting as a singleton "Scout Command" for all open windows.
*   **Antithesis**: Direct WebSocket connections in the main React component would cause catastrophic "DOM Thrashing" and block user input during market volatility.
*   **Synthesis**: We will create a `shared-worker.ts` file to manage the WebSocket connection to the "Bunker" and a `useSharedWorker` hook in React to communicate with it. This decouples data ingestion from rendering, ensuring a 60fps user experience.

---

### Step 20: SharedWorker Implementation

#### 20.1: Create `frontend/public/shared-worker.ts`
This file will live in the `public` directory so it can be accessed directly by the browser.

```bash
mkdir -p frontend/public
cat << 'EOF' > frontend/public/shared-worker.ts
/// <reference lib="webworker" />

// This declares the global scope for TypeScript to recognize SharedWorkerGlobalScope
declare const self: SharedWorkerGlobalScope;

const ports = new Set<MessagePort>();
let socket: WebSocket | null = null;

const connectWebSocket = () => {
    // The worker connects to the backend API gateway on the cloud machine.
    // Replace 'YOUR_CLOUD_VM_IP' with the actual IP or domain.
    // For local testing, you can use 'ws://localhost:8000/ws/stream' if you expose the port.
    const wsUrl = 'ws://app:8000/ws/stream'; // Using Docker service name
    console.log('[Worker] Attempting to connect to WebSocket:', wsUrl);

    socket = new WebSocket(wsUrl);

    socket.onopen = () => {
        console.log('[Worker] WebSocket connection established.');
        broadcast({ type: 'SYSTEM_STATUS', payload: 'WebSocket Connected' });
    };

    socket.onmessage = (event) => {
        // For now, just broadcast raw data. Throttling will be added later.
        broadcast({ type: 'DATA', payload: event.data });
    };

    socket.onclose = () => {
        console.log('[Worker] WebSocket disconnected. Reconnecting in 3s...');
        socket = null;
        broadcast({ type: 'SYSTEM_STATUS', payload: 'WebSocket Disconnected' });
        setTimeout(connectWebSocket, 3000);
    };

    socket.onerror = (error) => {
        console.error('[Worker] WebSocket error:', error);
        socket?.close();
    };
};

const broadcast = (message: any) => {
    const payload = JSON.stringify(message);
    ports.forEach(port => {
        port.postMessage(payload);
    });
};

self.onconnect = (e: MessageEvent) => {
    const port = e.ports[0];
    ports.add(port);
    console.log(`[Worker] UI client connected. Total clients: ${ports.size}`);

    port.onmessage = (event) => {
        // Handle messages from the UI if needed in the future
        console.log('[Worker] Message from UI:', event.data);
    };

    port.start();
};

// Initial connection
connectWebSocket();
EOF
```

#### 20.2: Create a React Hook to Manage the Worker (`frontend/src/shared/lib/useSharedWorker.ts`)

```bash
cat << 'EOF' > frontend/src/shared/lib/useSharedWorker.ts
import { useEffect, useState } from 'react';

export function useSharedWorker(onMessage: (data: any) => void) {
  const [status, setStatus] = useState('Connecting...');

  useEffect(() => {
    const worker = new SharedWorker(new URL('/shared-worker.ts', import.meta.url), { type: 'module' });

    worker.port.onmessage = (event: MessageEvent) => {
      try {
        const parsedData = JSON.parse(event.data);
        if (parsedData.type === 'SYSTEM_STATUS') {
          setStatus(parsedData.payload);
        } else {
          onMessage(parsedData);
        }
      } catch (e) {
        console.error("Failed to parse worker message:", event.data);
      }
    };

    worker.port.start();

    return () => {
      worker.port.close();
    };
  }, [onMessage]);

  return { status };
}
EOF
```

