import React, { useRef, useEffect, useState, useMemo } from 'react';
import { AgGridReact } from 'ag-grid-react';
import { ColDef } from 'ag-grid-community';
import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css'; // Using a default theme for now

interface LiveTickerGridProps {
  data: any[]; // Data comes from the parent (App.tsx)
}

export const LiveTickerGrid: React.FC<LiveTickerGridProps> = ({ data }) => {
  const gridRef = useRef<AgGridReact>(null);

  const [columnDefs] = useState<ColDef[]>([
    { field: 'symbol', headerName: 'Symbol', width: 120 },
    { field: 'lastPrice', headerName: 'Price', width: 120, cellStyle: { fontFamily: 'IBM Plex Mono' } },
    { field: 'timestamp', headerName: 'Timestamp', flex: 1 },
  ]);

  const getRowId = useMemo(() => {
    return (params: any) => params.data.symbol;
  }, []);

  useEffect(() => {
    if (gridRef.current?.api && data.length > 0) {
      gridRef.current.api.applyTransactionAsync({
        update: data,
      });
    }
  }, [data]);

  return (
    <div className="ag-theme-alpine-dark h-full w-full">
      <AgGridReact
        ref={gridRef}
        columnDefs={columnDefs}
        getRowId={getRowId}
        rowData={[]} // Initial data is empty, updates come via props
      />
    </div>
  );
};
EOF
```

#### 22.3: Update `frontend/src/app/App.tsx` to Feed Data to the Grid
This is the final step to connect the `SharedWorker` data stream to our new `LiveTickerGrid` widget.

```bash
cat << 'EOF' > frontend/src/app/App.tsx
import React, { useState, useCallback, useRef } from 'react';
import { Layout, Model, TabNode } from 'flexlayout-react';
import 'flexlayout-react/style/light.css';
import { layoutModel } from '@/shared/config/layoutConfig';
import { useSharedWorker } from '@/shared/lib/useSharedWorker';

// Import Widgets
import { LiveTickerGrid } from '@/widgets/live-ticker-grid/ui/LiveTickerGrid';
import { NewsFeed } from '@/widgets/news-feed/ui/NewsFeed';
import { StrategyControlPanel } from '@/widgets/strategy-control-panel/ui/StrategyControlPanel';
import { PriceChart } from '@/widgets/price-chart/ui/PriceChart';
import { LLMResearchCenter } from '@/widgets/llm-research-center/ui/LLMResearchCenter';

const model = Model.fromJson(layoutModel);

function App() {
  // State to hold the latest batch of data for the grid
  const [gridData, setGridData] = useState<any[]>([]);
  const dataBuffer = useRef<any[]>([]);

  const handleWorkerMessage = useCallback((message: any) => {
    try {
      const data = JSON.parse(message.payload);
      // For now, we'll just use the heartbeat as a mock data source for one symbol
      if (data.type === 'HEARTBEAT') {
        const mockTick = {
          symbol: 'SYSTEM_PULSE',
          lastPrice: new Date(data.timestamp).getSeconds(), // Use seconds as a changing price
          timestamp: data.timestamp,
        };
        // Buffer the update
        dataBuffer.current.push(mockTick);
      }
    } catch (e) {
      // Ignore non-JSON messages
    }
  }, []);

  useSharedWorker(handleWorkerMessage);

  // Use requestAnimationFrame to flush the buffer to React state
  React.useEffect(() => {
    let animationFrameId: number;
    const updateGrid = () => {
      if (dataBuffer.current.length > 0) {
        setGridData([...dataBuffer.current]);
        dataBuffer.current = [];
      }
      animationFrameId = requestAnimationFrame(updateGrid);
    };
    animationFrameId = requestAnimationFrame(updateGrid);
    return () => cancelAnimationFrame(animationFrameId);
  }, []);

  const factory = (node: TabNode) => {
    const component = node.getComponent();
    switch (component) {
      case 'liveTickerGrid':
        // Pass the live data to the grid component
        return <LiveTickerGrid data={gridData} />;
      case 'newsFeed':
        return <NewsFeed />;
      case 'strategyControlPanel':
        return <StrategyControlPanel />;
      case 'priceChart':
        return <PriceChart />;
      case 'llmResearchCenter':
        return <LLMResearchCenter />;
      default:
        return null;
    }
  };

  return (
    <div className="relative w-screen h-screen bg-neutral-100">
      <Layout model={model} factory={factory} />
    </div>
  );
}

export default App;
EOF
```

