import { test, expect } from '@playwright/test';

const BASE_URL = 'http://localhost:5173';

// A helper function for better logging on failure
async function runTestWithDiagnostics(page: any, testFn: () => Promise<void>) {
  try {
    await testFn();
  } catch (error) {
    console.error("--- TEST FAILED: DUMPING PAGE STATE ---");
    const html = await page.content();
    console.error("PAGE HTML:\n", html);
    await page.screenshot({ path: `test-failure-${Date.now()}.png`, fullPage: true });
    console.error("Screenshot saved to test-failure.png");
    console.error("--------------------------------------");
    throw error; // Re-throw the error to ensure the test is marked as failed
  }
}

